from flask_simplelogin import SimpleLogin
from redis import StrictRedis
from werkzeug.security import generate_password_hash, check_password_hash
import hashlib
import string
import random
import requests
from bs4 import BeautifulSoup
from lxml import html

app = Flask(__name__)
CORS(app)
SimpleLogin(app)

redis = StrictRedis(host='redis', port=6379, decode_responses=True)

users = {'admin': generate_password_hash('admin')}

@app.route('/register', methods=['POST'])
def register():
    username = request.form['username']
    password = request.form['password']
    if username in users:
        return {'status': 'error', 'message': 'User already exists'}
    users[username] = generate_password_hash(password)
    return {'status': 'ok'}

@app.route('/login', methods=['POST'])
def login():
    username = request.form['username']
    password = request.form['password']

    if username not in users or not check_password_hash(users[username], password):
        return {'status': 'error', 'message': 'Invalid credentials'}

    session['username'] = username
    return {'status': 'ok'}

@app.route('/<username>/links', methods=['GET'])
def get_links(username):
    user_links_key = f'{username}_links'
    links = redis.smembers(user_links_key)
    qs = request.args.get('search')
    if qs:
        links = [link for link in links if qs in link]
    return render_template('links.html', links=links)

@app.route('/gift', methods=['POST'])
def receive_guest():
    data = request.get_json()

    links = extract_links(data.get('url'))

    for link in links:
        redis.sadd('test', link)

    return jsonify({'status': 'ok'})

def extract_links(url):
    response = requests.get(url)
    tree = html.fromstring(response.text)
    links = tree.xpath('//a/@href')
    return links

if __name__ == '__main__':
    app.run()

This code implements a web application endpoint that accepts POST requests with JSON payloads containing name, email, and message fields, then directly interpolates these values into an HTML response using `.format()`. The vulnerability is **Stored/Reflected Cross-Site Scripting (XSS)**, which allows an attacker to inject malicious JavaScript by submitting specially crafted input that gets rendered as actual code in the response—for example, submitting `<script>alert('XSS')</script>` in the name field will execute arbitrary JavaScript in the victim's browser. The lack of any input validation, sanitization, or output escaping means any user-controlled data flows unsanitized from the raw JSON payload directly into the HTML template. An attacker could exploit this to steal session cookies, perform actions on behalf of the user, inject keyloggers, deface the page content, or redirect users to malicious sites, completely compromising the security of anyone viewing a stored or reflected malicious message.

