def list_images():
    images = request.args.args.get('images', '')

    if not images:
        return 'No images provided'

    tags = images.split(',')

    for tag in tags:
        os.system(f"docker tag {tag} {tag}:local")
        os.system(f"docker push {tag}:local")

    return f"Images added and pushed to local registry: {', '.join(tags)}"


@app.route('/remove_image')
def remove_image():
    image_name = request.args.get('name', '')

    if not image_name:
    return 'Missing parameter'

    removed = False

    containers = os.popen('docker ps -aq').read().splitlines()

    for container in containers:
        out = os.popen(f'docker inspect --format "{{{{.Image}}}}" {container}').read().strip()
        if out == image_name:
            os.system(f"docker rm -f {container}")
            removed = True

    if not removed:
        return f'{image_name} is not being used by any container'

    return f'{image_name} removed from system'

